import axios from 'axios';

const API_URL = `${process.env.REACT_APP_API_URL || 'http://localhost:5000/api'}/auth`;

export const authService = {
  login: async (role = 'STUDENT', username, password) => {
    // For hackathon purposes, we use username as email and password as the ID
    const email = username ? `${username}@skillproof.test` : 'student@test.com';
    const pwd = password || '123456';
    
    try {
      // Try logging in
      const res = await axios.post(`${API_URL}/login`, { email, password: pwd });
      return res.data;
    } catch (err) {
      // If login fails (user doesn't exist), register them automatically for seamless UX
      if (err.response && err.response.status === 400) {
        const res = await axios.post(`${API_URL}/register`, {
          role,
          name: username || 'Test User',
          email,
          password: pwd,
          company: role === 'RECRUITER' ? 'Test Company' : undefined
        });
        return res.data;
      }
      throw err;
    }
  },
  loginWithToken: async (token) => {
    try {
      const res = await axios.get(`${API_URL}/me`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      return { token, user: res.data };
    } catch (err) {
      console.error('Failed to login with token', err);
      throw err;
    }
  },
  logout: () => {
    return true;
  },
  getCurrentUser: async () => {
    const token = JSON.parse(localStorage.getItem('user'))?.token;
    if (!token) return null;
    
    try {
      const res = await axios.get(`${API_URL}/me`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      return res.data;
    } catch (err) {
      console.error('Failed to get user', err);
      return null;
    }
  }
};
